sys_ux_client_script.script:
function handler({ api, event, helpers }) {
    const values = api.state.formValues || {};
    const errors = {
        firstName: "",
        lastName: "",
        userName: "",
        email: "",
        password: ""
    };

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const userNameRegex = /^[a-zA-Z0-9_]{3,20}$/;
    const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;

    if (!values.firstName || !values.firstName.trim()) {
        errors.firstName = "First Name is required.";
    }

    if (!values.lastName || !values.lastName.trim()) {
        errors.lastName = "Last Name is required.";
    }

    if (!values.userName || !values.userName.trim()) {
        errors.userName = "Username is required.";
    } else if (!userNameRegex.test(values.userName)) {
        errors.userName = "Username must be 3-20 alphanumeric characters.";
    }

    if (!values.email || !values.email.trim()) {
        errors.email = "Email address is required.";
    } else if (!emailRegex.test(values.email)) {
        errors.email = "Please enter a valid email address.";
    }

    if (!values.password) {
        errors.password = "Password is required.";
    } else if (!passwordRegex.test(values.password)) {
        errors.password = "Password must meet complexity requirements.";
    }

    const isValid = !Object.values(errors).some(err => err !== "");

    api.setState('errors', errors);
    api.setState('isFormValid', isValid);

    return isValid;
}
